'''
def multiline_iterable(
    iterable,
    separator=", ",
    max_line_length=100,
    indent="",
    extra_indent="  ",
    linebreak="",
    prefix="[",
    suffix="]",
    prefix_suffix_lines=True,
):
    """
    Generate the lines of a written representation of a list-like object.

    :param iterable: the iterable to be translated to text
    :param separator: separator that connects elements, e.g. ", "
    :param max_line_length: maximum line length before line break comes
    :param indent: indentation to be included in every line
    :param extra_indent: extra indent after the first line
    :param linebreak: a linebreak character, required by some languages
    :param prefix: before list starts
    :param suffix: after list ends
    :param head_tail_lines: head_tail_lines

    """

    # prepare the data, copy, make list, ...
    listlike = list(iterable)
    not_empty = len(listlike) > 0

    # the first element is treated differently, as it does not require a separator in front
    is_first = True

    # if prefix and suffix are in separate lines, start here
    if prefix_suffix_lines:
        # yield extra head line, then prepare next. No size check here!
        line = indent + prefix
        fill = max(0, (max_line_length - len(line) - len(linebreak))) * " "
        if prefix:
            yield line + fill + linebreak
            line = indent + extra_indent
        else:
            line = indent
    else:
        # start with indented and headed line but don't yield yet
        line = indent + prefix

    # go through listlike
    while listlike:
        # pop first in list
        string = str(listlike.pop(0))

        # check if can be appended or new line required
        if (
            len(line + separator + string + separator + linebreak)
            <= max_line_length
        ):
            # can be appended: append (w/ or w/o separator)
            if is_first:
                line += string
                is_first = False
            else:
                line += separator + string
        else:
            # can not be appended. Append only separator, space-pad and yield
            line += separator
            fill = (max_line_length - len(line) - len(linebreak)) * " "
            yield line + fill + linebreak
            # and put in next line
            line = indent + extra_indent + string

    # if prefix and suffix are in separate lines, treat here
    if prefix_suffix_lines:
        # first, handle not yet yielded lines.
        if line and not_empty:
            # not empty check: empty list would get create an extra emtpy line only with indent!
            fill = (max_line_length - len(line) - len(linebreak)) * " "
            yield line + fill + linebreak
        if suffix:
            # extra suffix line
            yield indent + suffix
    else:
        # again, take care of leftover line, but attempt to append suffix.
        if len(line + suffix) <= max_line_length:
            yield line + suffix
        else:
            yield line + linebreak
            if suffix:
                yield indent + suffix
'''


class CodeContainer:
    """
    A Codecontainer is a fundamental building block in the code that is
    ultimately generated. This is the internal base class that includes
    anything that is not yet language specific.

    """

    INDENT_BODY = False
    comment_class = None

    def __init__(self, *, context, **_) -> None:
        # all content that may or may not be useful
        # self._data: Dict[str, Any] = {}

        # collect variables that are used here
        # self._requirements: Set[str] = set()

        # content, divided in three sections, head, body, foot
        self._container_body: list[CodeContainer] = []

        # self._memory = {}

        self._context = context.inherit().set_container(self)

        self._attachment_point = self

        # # parent link
        # self._wr_parent: wrReferenceType[CodeContainer] | None = None
        # self._set_parent(
        #     context.parent
        # )  # manage parent reference, might be weak

    def set_attachment_point(self, point: CodeContainer) -> None:
        """set the point where containers are effectively attached"""
        self._attachment_point = point

    @Namespace.wrap_name_combine
    def request_temp(self, name, generating, autorequire=True, **genargs):
        """
        Request a temporary variable from a namespace
        """
        # if variable is known to namespace already, get a new one.
        # the counter of local variables of the proper type tells
        # if a new variable has to be made.
        temp = self.namespace.request_temp(
            generating,
            name=name,
            origin=self,
            **genargs,
        )
        if autorequire:
            self.requires(temp)
        return temp

    @Namespace.wrap_name_combine
    def request_unique(self, name, generating, autorequire=True, **genargs):
        """
        Request a unique variable from a namespace
        """
        # if variable is known to namespace already, get a new one.
        # the counter of local variables of the proper type tells
        # if a new variable has to be made.
        temp = self.namespace.request_unique(
            generating,
            name=name,
            origin=self,
            **genargs,
        )
        if autorequire:
            self.requires(temp)
        return temp

    @Namespace.wrap_name_combine
    def request_new(
        self,
        name,
        generating,
        *args,
        autorequire=True,
        **kwargs,
    ):
        """
        Request any new variable type from a namespace. Use autoname if necessary.
        """
        # TODO
        variable = self.namespace.request_variable(
            generating,
            name,
            *args,
            **kwargs,
            enum_first=True,
        )
        if autorequire:
            self.requires(variable)
        return variable

    def request_assigned(self, ivariable_type, key, autorequire=True):
        """find a variable in the attached namespace"""
        variable = self.namespace.find_assignment(
            ivariable_type, key, exception_existing=False
        )
        if variable is None:
            return None
        if autorequire:
            self.requires(variable)
        return variable

    def requires(self, variable: LibRoutineVariable) -> None:
        """request to use a variable"""
        # potentially gets stuck in CaptureContainer
        # self._requirements.add(variable.name)
        if not isinstance(variable, LibRoutineVariable):
            raise TypeError("Dependencies must be LibRoutineVariables")
        if self.parent is None:
            raise ValueError(
                f"variable request got lost for variable {variable} ({variable.vtype})!"
            )
        self.parent.requires(variable)

    def codelines_from_text(self, text: str, context=None) -> CodeContainer:
        """generate a plain codeline from text"""
        if context is None:
            context = self.context
        for line in text.split("\n"):
            yield CodeLine(
                line=text,
                context=context,
            )

    def build(self, **_):
        """build the container"""
        return self

    def build_all(self):
        """call build on the whole container"""
        for container in self.content:
            container.build_all()
        self.build()
        return self

    def reset(self, **_):
        """perform a reset on this container"""
        # if you reset captures, they cannot be recovered if they are required outside build!
        # self.reset_captured()
        return self

    def reset_all(self, **kwargs):
        """
        Reset the container. Default behaviour:
        - reset the head and foot containers
        - call reset on whole container body
        """
        self.reset(**kwargs)
        for container in self.content:
            container.reset_all(**kwargs)
        return self

    def get_codelines_body(
        self, indent: int, **kwargs: Any
    ) -> Generator[str, None, None]:
        """
        Get the codelines from the body section of the container.
        This yields text and/or forwards into other containers.
        """
        if self._container_body is not None:
            for content in self._container_body:
                yield from content.get_codelines(indent=indent, **kwargs)

    def get_indent(self, level: int = 0) -> str:
        """convert the indent level into a string"""
        return "  " * level

    def append(self, content):
        """append to the container body"""
        self._attachment_point.append_body(content)

    @property
    def context(self):
        """access the context but prohibit setting it manually"""
        return self._attachment_point._context

    @property
    def level(self):
        """access the level but prohibit setting it manually"""
        return self.context.level

    @property
    def namespace(self):
        """access the namespace but prohibit setting it manually"""
        return self.context.namespace

    @property
    def environment(self):
        """access the environment but prohibit setting it manually"""
        return self.context.environment

    @property
    def parent(self):
        """access the parent but prohibit setting it manually"""
        return self.context.parent

    @property
    def body(self):
        """iterate through body content only"""
        yield from self._container_body

    @property
    def content(self):
        """iterate through foot content only"""
        yield from self.body

    def get_codelines(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        """get the codelines from the container"""
        yield from self.get_codelines_body(indent, **kwargs)

    def reset_captured(self) -> None:
        """reset the provided requirements"""
        for content in self.content:
            content.reset_captured()

    def append_body(self, *containers: CodeContainer) -> None:
        """append at body"""
        for container in containers:
            if container is None:
                continue
            self._container_body.append(container)

    @classmethod
    def set_comment_class(cls, comment_gen):
        """set the comment generator"""
        cls.comment_class = comment_gen

    def comment_from_text(self, text, **buildargs):
        """generate one or multiple comment lines"""
        if type(self).comment_class is not None:
            for cline in text.split("\n"):
                assert callable(type(self).comment_class)
                yield type(self).comment_class(
                    cline,
                    context=self.context,
                    **buildargs,
                )


class EmptyLines(CodeContainer):
    """An Empty Line (or multiple)"""

    def __init__(self, num=1, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._num_empty_lines = num

    def get_codelines_body(self, indent=0, **kwargs):
        for _ in range(self._num_empty_lines):
            yield indent, ""


class EmbeddingContainer(CodeContainer):
    """
    A container that is embedded in head and foot lines.
    """

    def __init__(self, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._container_head: list[CodeContainer] = []
        self._container_foot: list[CodeContainer] = []

    def append_head(self, *containers: CodeContainer) -> None:
        """append at head"""
        for container in containers:
            if container is None:
                continue
            self._container_head.append(container)

    def append_foot(self, *containers: CodeContainer) -> None:
        """append at foot"""
        for container in containers:
            if container is None:
                continue
            self._container_foot.append(container)

    def get_codelines_head(
        self, indent: int, **kwargs: Any
    ) -> Generator[str, None, None]:
        """
        Get the codelines from the head section of the container.
        This yields text and/or forwards into other containers.
        """
        if self._container_head is not None:
            for content in self._container_head:
                yield from content.get_codelines(indent=indent, **kwargs)

    def get_codelines_foot(
        self, indent: int, **kwargs: Any
    ) -> Generator[str, None, None]:
        """
        Get the codelines from the foot section of the container.
        This yields text and/or forwards into other containers.
        """
        if self._container_foot is not None:
            for content in self._container_foot:
                yield from content.get_codelines(indent=indent, **kwargs)

    def get_codelines(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        """get the codelines from the container"""
        yield from self.get_codelines_head(indent, **kwargs)
        yield from super().get_codelines(
            indent + int(self.INDENT_BODY), **kwargs
        )
        yield from self.get_codelines_foot(indent, **kwargs)

    def generate_head_containers(self):
        """build the head section of the container"""
        return
        yield

    def generate_foot_containers(self):
        """build the foot section of the container"""
        return
        yield

    def build(self, **_):
        for container in self.generate_head_containers():
            self.append_head(container)
        for container in self.generate_foot_containers():
            self.append_foot(container)
        return super().build()

    def reset(self, **_):
        """perform a reset on this container"""
        self._container_head: list[CodeContainer] = []
        self._container_foot: list[CodeContainer] = []
        return super().reset()

    @property
    def head(self):
        """iterate through head content only"""
        yield from self._container_head

    @property
    def foot(self):
        """iterate through foot content only"""
        yield from self._container_foot

    @property
    def content(self):
        """iterate through foot content only"""
        yield from self.head
        yield from super().content
        yield from self.foot


class PreambleContainer(CodeContainer):
    """A container allowing for a preamble"""

    def __init__(self, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._container_prmb: list[CodeContainer] = []

    def get_codelines_preamble(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        if self._container_prmb is not None:
            for content in self._container_prmb:
                yield from content.get_codelines(indent=indent, **kwargs)

    def get_codelines(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        """get the codelines from the container"""
        yield from self.get_codelines_preamble(
            indent + int(self.INDENT_BODY), **kwargs
        )
        yield from super().get_codelines(
            indent + int(self.INDENT_BODY), **kwargs
        )

    def generate_preamble_containers(self):
        """build the preamble section of the container"""
        return
        yield

    def build(self, **_):
        for container in self.generate_preamble_containers():
            self.append_preamble(container)
        return super().build()

    def reset(self, **_):
        """perform a reset on this container"""
        self._container_prmb: list[CodeContainer] = []
        return super().reset()

    def append_preamble(self, *containers: CodeContainer) -> None:
        """append at preamble"""
        for container in containers:
            if container is None:
                continue
            self._container_prmb.append(container)

    @property
    def preamble(self):
        """iterate through foot content only"""
        yield from self._container_prmb

    @property
    def content(self):
        """iterate through foot content only"""
        yield from self.preamble
        yield from super().content


class NamedContainer(CodeContainer):
    """A named region container. Simply provides the name attribute"""

    def __init__(self, name, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._name = name

    @property
    def name(self):
        """access name"""
        return self.create_name()

    def create_name(self):
        """
        create the name from context, especially when it is not
        just the name straightforwardly"""
        return self._name

    @property
    def content(self):
        """iterate through foot content only"""
        yield from super().content


class GroupContainer(EmbeddingContainer):
    """
    A holds multiple containers inside. The grouping might only be symbolically.
    Head and Foot are not occupyable by anything other than formal enclosings
    delimiters and comments.
    """

    def append(self, content):
        """group containers provide empty lines for clarity and proper separation"""
        if len(self._container_body) > 0:
            self._container_body.append(EmptyLines(1, context=self.context))
        super().append(content)


class CodeBlock(CodeContainer):
    """A block of code that can only contain codelines but no control structures"""

    # should default to getting the content of body without any extras.
    def append(self, content):
        """append a container to the body"""
        if not isinstance(content, (CodeLine, CodeBlock)):
            raise TypeError("Can only add CodeLine leaf nodes to CodeBlock")
            # if a codeblock is added, it can only have codelines in it.
            # or codeblocks, but those can only contain codelinexs themselves.
            # or codeblocks, but those can only contain codelines themselves.
            # ...
            # you get it.
        super().append(content)


class CodeLine(CodeContainer):
    """Recursion-Breaking. Literally a single line. Leaf container base class."""

    def __init__(self, line=None, *, context, **params):
        super().__init__(context=context, **params)
        self._line = line

    def get_codelines_body(self, indent, **kwargs):
        """
        When the codelines are requested, the container generates them on the fly.
        Therefore, the content stays dynamic until the code is completely generated
        and ready to be created.
        """
        for line in self.construct_code_lines(**kwargs):
            yield indent, line

    @property
    def line(self):
        """access hidden attribute line"""
        if self._line is None:
            return ""
        return self._line

    @line.setter
    def line(self, line):
        """write-access. Maybe disallow in the future."""
        self.set_line(line)

    def append_body(self, *_):
        raise ValueError("Cannot append to head in CodeLine")

    def set_line(self, line):
        """set the line"""
        if not isinstance(line, str):
            raise TypeError("Line must be a string")
        if "\n" in line:
            raise ValueError("Line cannot contain newline")
        self._line = line
        return self

    def format(self, **replacements):
        """format the line using replacements"""
        self._line = self._line.format(**replacements)

    def construct_code_lines(self, **_):
        """construct the code line"""
        # this is a generator to include line breaks if necessary
        yield self.line


class StatementLine(CodeLine):
    """
    A statement of form
      output = somefunction(input1, ...)
      output = input[index]
      output = input
      output = input1 some_operator input2

    Serves as base class for more specific statements, but handles the variable
    dependencies
    """

    BLUEPRINT = ""

    def __init__(self, value_dict, *, context, **params):
        super().__init__(
            context=context,
            **params,
        )
        self._value_dict = value_dict
        self.extend_value_dict()

    def set_value(self, key, value):
        """set the value in the value dict"""
        self._value_dict[key] = value

    def extend_value_dict(self):
        """extend the value dict by some parameters created from other parameters"""
        return self

    def construct_code_lines(self):
        yield type(self).BLUEPRINT.format(**self._value_dict)


class CommentLine(CodeLine):
    """
    This line represents a comment
    """

    COMMENT_PREFIX = "#"

    def construct_code_lines(self, **_):
        yield type(self).COMMENT_PREFIX + self.line


class DefinitionLines(CodeLine):
    """
    This line represents a comment
    """

    def __init__(self, variable, *, context, **params):
        super().__init__(line=None, context=context, **params)
        self.set_variable(variable)

    @property
    def variable(self):
        """acccess variable"""
        return self._variable

    def construct_code_lines(self, **_):
        yield from self._variable.get_definition_lines()

    def set_variable(self, variable):
        """set the variable. Maybe disallow that later."""
        self._variable = variable
        return self


