class DefinitionContainer(CaptureContainer, PreambleContainer):
    """
    A code container that defines stuff and prevents them from getting passed
    on during requirement iterator. Supports a filtering function that decides
    on which type of requirements are implemented here or passed on.
    """

    INDENT_BODY = False

    def generate_preamble_containers(self, **kwargs):
        for variable in self.captured:
            yield DefinitionLines(variable, context=self.context, **kwargs)


class HiddenLayersContainer(CodeContainer):
    """Provide Hidden Layer Functionality"""

    def __init__(self, *args, context, **buildargs):
        inner_context = self._prep_hidden_layers_pre(context, **buildargs)
        super().__init__(*args, context=inner_context, **buildargs)
        last_container = self._prep_hidden_layers_post(
            inner_context, self, **buildargs
        )
        self.set_attachment_point(last_container)

    def _prep_hidden_layers_pre(self, context, **_):
        return context

    def _prep_hidden_layers_post(self, _context, container=None, **_buildargs):
        if container is None:
            container = self
        return container


class RoutineContainer(
    NamedContainer,
    HiddenLayersContainer,
    EmbeddingContainer,
    PreambleContainer,
):
    """
    How a routine is defined, especially handles the section where the arguments
    are passed and opening/enclosing statements.
    """

    # should provide a string how the routine is called
    # should provide a general signature database for imports
    # libraries can provide that and when a library is imported, the
    # signatures are provided

    INDENT_BODY = True
    DEFAULT_MULTIFRAME_CLASS = MultiFrameContainer

    def __init__(
        self, name, *, context, multiframe_container_class=None, **buildargs
    ):
        if multiframe_container_class is None:
            multiframe_container_class = type(self).DEFAULT_MULTIFRAME_CLASS
        self._mfcontainer_class = multiframe_container_class

        unique_name = UniqueString(name, namespace=context.namespace)
        context.namespace.add(unique_name)

        super().__init__(name=unique_name.name, context=context, **buildargs)

        # added in hidden - pre
        self._var_layer.add_capture_trigger(LibRoutineInputVariable)
        self._var_layer.add_capture_trigger(LibRoutineOutputVariable)
        self._var_layer.add_capture_trigger(LibRoutineInOutVariable)
        self._def_layer.add_capture_trigger(LibRoutineLocalVariable)

    def _prep_hidden_layers_pre(self, context, **buildargs):
        self._def_layer = CaptureContainer(
            context=context,
            **buildargs,
        )
        self._var_layer = CaptureContainer(
            context=self._def_layer.context, **buildargs
        )
        return super()._prep_hidden_layers_pre(
            self._var_layer.context, **buildargs
        )

    def _prep_hidden_layers_post(self, context, container=None, **buildargs):
        self._rep_layer = LoopCaptureContainer(
            self._mfcontainer_class,
            context=context,
            **buildargs,
        )
        container.append_body(self._rep_layer)
        return super()._prep_hidden_layers_post(
            self._rep_layer.context, self._rep_layer, **buildargs
        )

    # def get_call_arguments(self, **substitutions):
    #     """list the arguments needed for a call"""
    #     for variable in self.get_argument_variables():
    #         yield variable.as_argument()

    def get_argument_variables(self, **_):
        """list the variables that show up in the argument list"""
        for variable in self._var_layer.captured:
            yield variable

    def get_inner_variables(self, **_):
        """list the inner variables"""
        for variable in self._def_layer.captured:
            yield variable

    def generate_preamble_containers(self, **kwargs):
        """
        distribute the captured variables into the def line and the call
        """
        yield from self.comment_from_text("IN/OUT/INOUT")
        for variable in self.get_argument_variables():
            yield DefinitionLines(variable, context=self.context, **kwargs)
        yield from self.codelines_from_text("")
        yield from self.comment_from_text("LOCAL")
        for variable in self.get_inner_variables():
            yield DefinitionLines(variable, context=self.context, **kwargs)
        yield from self.codelines_from_text("")

    def generate_head_containers(self, **_):
        call_args = (
            variable.as_argument()
            for variable in self.get_argument_variables()
        )
        yield from self.codelines_from_text(
            f":BEGIN: FUNCTION {self.name} ({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f":END: FUNCTION {self.name}")

    # def get_call_codelines(self, **substitutions):
    #     """
    #     Get the string of how to call it. Plug the proper substitutions into
    #     the argument line.
    #     Use get_call_arguments to get the arguments in the format designed for
    #     a call.
    #     """


class KernelContainer(RoutineContainer):
    """
    A KernelContainer represents a piece of code that is supposed to be called
    in various memory locations, potentially simultaneously. KernelContainers
    might map to parametrized auxilliary functions or actual kernels on GPUs.

    An instruction block from a map instruction is preferably rendered into a
    kernel. Kernels are treated as subtypes of functions. They manage frame selectors
    and map them to external parallel ressources.

    Kernel Containers provide some management for frame selectors.

    Current idea:

    The kernel is a routine that is designed for a parallel call


    # Build strategy, maybe do not put all of that here!
    Collect all frame_selectors that are handled inside the kernel group.
    a new (most inner) layer gets assigned to the most inner selector and whatever
    was assigned there before travels one layer up.
    After the highest kernel-layer, the selectors need to map to loops outside of the call!
    In my current strategy, I do not consider that part of the kernel call as well.
    The kernel itself is only the routine-like object with information on how it
    is called. The loops and other call attributes are invoked in a kernalize container
    """

    def __init__(self, name, *, context, **buildargs):
        super().__init__(name, context=context, **buildargs)
        self._ker_layer.add_capture_trigger(LibRoutineMultiFrame)
        self._rep_layer = None

    def _prep_hidden_layers_pre(self, context, **buildargs):
        self._def_layer = CaptureContainer(context=context, **buildargs)
        self._var_layer = CaptureContainer(
            context=self._def_layer.context, **buildargs
        )
        self._ker_layer = CaptureContainer(
            context=self._var_layer.context, **buildargs
        )
        return self._ker_layer.context

    def _prep_hidden_layers_post(self, context, container=None, **buildargs):
        # directly return self, because super()._.._post includes the LoopContainer
        return self

    # def get_call_arguments(self, **substitutions):
    #     for variable in self.get_argument_variables():
    #         yield variable.as_argument()

    def get_kernel_variables(self):
        """get the kernel multiframe variables"""
        for variable in self._ker_layer.captured:
            yield variable

    def prepare_kernel_arguments(self):
        """prepare the multiframe variables among the arguments"""
        for variable in self.get_kernel_variables():
            variable.create_input_representative(
                context=self.context,
                dtype="i32",
                size=None,
                prefix="krnl",
            )

    def build(self, **kwargs):
        # first handle kernel args (requested during creation)
        # then build the rest, knowing the local representation
        self.prepare_kernel_arguments()
        return super().build(**kwargs)

    def generate_head_containers(self, **_):
        call_args = (
            variable.as_argument()
            for variable in self.get_argument_variables()
        )

        yield from self.codelines_from_text(
            f":BEGIN: KERNEL FUNCTION {self.name} ({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(
            f":END: KERNEL FUNCTION {self.name}"
        )

    # def get_call_codelines(self, context, **substitutions):
    #     """
    #     Get the string of how to call it. Plug the proper substitutions into
    #     the argument line.
    #     Use get_call_arguments to get the arguments in the format designed for
    #     a call.
    #     """


class ImportContainer(CodeLine):
    """Import a routine or routine-like object"""

    def __init__(self, library, routines, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._library = library
        self._routines = routines

    def construct_code_lines(self, **_):
        """create the codelines required for the import"""
        for routine in self._routines:
            yield f":IMPORT: {routine.name} from {self._library.name}"


class RoutineCallContainer(CodeLine):
    """Call a routine or routine-like object"""

    def __init__(self, external_routine, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._ext_routine = external_routine
        self._call_args = []
        for assignment in external_routine.get_argument_assignments():
            source, key = assignment
            if isinstance(source, LibRoutineMultiFrame):
                local = source.recreate()
                self.requires(local)
            else:
                local = self.request_assigned(source, key, autorequire=True)
            self._call_args.append(local)
        self.requires(self._ext_routine)

    def construct_code_lines(self, **_):
        # call name depends on import section
        call_args = [
            call_arg.local
            if isinstance(call_arg, LibRoutineMultiFrame)
            else call_arg
            for call_arg in self._call_args
        ]
        call_arg_names = [call_arg.as_argument() for call_arg in call_args]
        call_string = f":CALL: {self._ext_routine.call_name}({', '.join(call_arg_names)})"
        yield call_string

    # generate the call using info from the ExternalRoutine variable


class ImportSectionContainer(CaptureContainer, EmbeddingContainer):
    """Capture all imports"""

    DEFAULT_IMPORT_LINE_CLASS = ImportContainer

    def __init__(self, *, context, import_line_class=None, **buildargs):
        super().__init__(context=context, **buildargs)
        if import_line_class is None:
            import_line_class = type(self).DEFAULT_IMPORT_LINE_CLASS
        self._import_line_class = import_line_class
        self._grouped_imports = []
        self.add_capture_trigger(ExternalRoutine)

    def list_imports(self):
        """list the imports in the format (library, [routine1, routine2, ...])"""
        yield from self._grouped_imports

    def manage_captured(self, **kwargs):
        # called in build. Preselect and check the imports
        captured_imports = []
        self._grouped_imports = []
        for to_be_imported in self._captured:
            # check for compatibility
            if not self.compatibility_check(to_be_imported):
                raise ValueError(
                    f"Library {to_be_imported.library} does not match current library"
                )
            captured_imports.append(to_be_imported)

        # add the import codelines to the body. tidy_imports does the grouping
        for library, routines in self.tidy_imports(captured_imports):
            self._grouped_imports.append((library, routines))
            for routine in routines:
                routine.set_call_name(self.compose_call_name(routine, library))

    def generate_head_containers(self, **kwargs):
        for library, routines in self._grouped_imports:
            yield self._import_line_class(
                library, routines, context=self.context, **kwargs
            )

    def compose_call_name(self, routine, library):
        """compose the name of the call"""
        return f"{library.name}.{routine.name}"

    def tidy_imports(self, list_of_imports):
        """tidy the imports, i.e. handle groups, repeats, ..."""
        for this_import in list_of_imports:
            yield this_import.library, [this_import]

    def compatibility_check(self, _to_be_imported):
        """check if libroutine is compatible"""
        # print(f"... check import of {to_be_imported} ({to_be_imported.name})")
        return True

    def reset(self, **kwargs):
        self._grouped_imports = []
        return super().reset(**kwargs)


class LoopCaptureContainer(CaptureContainer, EmbeddingContainer):
    """A capture container that reacts on multi frame objects"""

    INDENT_BODY = True

    def __init__(self, mfcontainer_class, *, context, **buildargs):
        super().__init__(context=context, **buildargs)
        self._mfcontainer_class = mfcontainer_class
        self.add_capture_trigger(LibRoutineMultiFrame)
        self._repeat_containers = []

    def manage_captured(self, **kwargs):
        for num, variable in enumerate(self.captured):
            self._repeat_containers.append(
                self._mfcontainer_class(context=self.context, **kwargs)
                .set_multiframe_variable(
                    variable,
                    prefix=f"cnt_l{self.level}_n{num}",
                )
                .build_all()
            )

    def get_codelines_head(self, indent: int, **kwargs):
        for num, container in enumerate(self._repeat_containers):
            yield from container.get_codelines_head(
                indent + num * int(self.INDENT_BODY), **kwargs
            )

    def get_codelines_foot(self, indent: int, **kwargs):
        reversed_containers = list(enumerate(self._repeat_containers))[::-1]
        for num, container in reversed_containers:
            yield from container.get_codelines_foot(
                indent + num * int(self.INDENT_BODY), **kwargs
            )

    def get_codelines(self, indent: int, **kwargs):
        yield from self.get_codelines_head(indent, **kwargs)
        yield from self.get_codelines_body(
            indent + int(self.INDENT_BODY) * len(self._repeat_containers),
            **kwargs,
        )
        yield from self.get_codelines_foot(indent, **kwargs)

    def reset(self):
        self._repeat_containers = []
        return super().reset()


class LibraryContainer(NamedContainer, EmbeddingContainer, PreambleContainer):
    """
    A Library contains routines, constants and more.
    The Library Container provides generalized routines to add
    libroutines, imports, constants, ... that can be called
    """

    def __init__(self, name, *, context, **buildargs):
        # print("library init")
        self._imp_layer = ImportSectionContainer(context=context)
        self._def_layer = DefinitionContainer(context=self._imp_layer.context)
        super().__init__(name, context=self._def_layer.context, **buildargs)
        self._def_layer.add_capture_trigger(LibRoutineConstant)
        self._imp_layer.add_capture_trigger(ExternalRoutine)

    def build(self):
        self._imp_layer.build()
        self._def_layer.build()
        return super().build()

    def generate_preamble_containers(self, **_):
        yield from self.codelines_from_text("# IMPORTS")
        yield self._imp_layer
        yield from self.codelines_from_text("")
        yield from self.codelines_from_text("# CONSTANTS")
        yield self._def_layer
        yield from self.codelines_from_text("")
        yield from self.codelines_from_text("# ROUTINES")
        yield from self.codelines_from_text("")

    def generate_head_containers(self, **_):
        """make the enclosings for this container"""
        yield from self.codelines_from_text(f"LIBRARY {self.name}")

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f"END LIBRARY {self.name}")

